<script setup lang="ts">
import type { LudiView, LudiSession } from '@doot-games/games/ludi/contracts'
import { ludiActionId, type ConnectionState } from '../utils/ludi-session'
const props = defineProps<{ view: LudiView; session: LudiSession; connection?: ConnectionState }>()
const choice = ref<number | null>(null), text = ref(''), busy = ref(false), error = ref('')
const heading = ref<HTMLElement>(), controls = ref<HTMLElement>(), height = ref(150)
let observer: ResizeObserver | undefined
watch(controls, el => { observer?.disconnect(); if (el) { observer = new ResizeObserver(() => height.value = Math.ceil(el.getBoundingClientRect().height)); observer.observe(el) } })
onUnmounted(() => observer?.disconnect())
const content = computed(() => props.view.content)
const options = computed(() => content.value && 'options' in content.value ? content.value.options : [])
const answer = computed(() => props.view.actions.find(a => a.type === 'answer'))
const ended = computed(() => props.connection?.state === 'ended')
const primary = computed(() => ended.value ? undefined : props.view.actions.find(a => a.type !== 'skip'))
const conversation = computed(() => content.value?.kind === 'conversation')
const label = computed(() => ({ 'quick-choice': 'Vai pela tua', sync: 'Em sintonia?', story: 'Uma história', perception: 'Entre vocês', custom: 'Quem me conhece?', prediction: 'Um palpite sobre alguém', 'who-here': 'Quem aqui…?' } as Record<string,string>)[content.value && 'momentType' in content.value ? content.value.momentType ?? '' : ''] ?? 'Entre Nós')
const missing = computed(() => {
  const p = props.view.participation
  const ids = props.view.reveal ? props.view.players.map(v => v.id).filter(id => !p?.ready.includes(id)) : p?.eligible.filter(id => !p.answered.includes(id)) ?? []
  return props.view.players.filter(p => ids.includes(p.id)).map(p => p.name).join(', ')
})
const wait = computed(() => props.view.reveal ? `Vamos continuar quando ${missing.value || 'o grupo'} estiver pronto.` : props.view.stage === 'prediction' && !answer.value && props.view.ownChoice === undefined && !props.view.skipped ? 'O grupo está a prever a tua escolha. A seguir respondes tu.' : `Falta ${missing.value || 'o resto do grupo'}. Cada pessoa pode responder ou passar.`)
const revealTitle = computed(() => props.view.reveal?.targetSkipped ? 'Fica para outra vez.' : conversation.value ? 'O que partilhámos.' : props.view.reveal?.correctLabel ? 'Descobrimos!' : (props.view.reveal?.counts ?? []).filter(n => n > 0).length === 1 ? 'Em sintonia!' : (props.view.reveal?.counts ?? []).some(n => n > 0) ? 'Cada um à sua maneira.' : 'Hoje passámos todos.')
const totalVotes = computed(() => props.view.reveal?.counts?.reduce((a,b) => a+b,0) || 1)
const key = computed(() => `${props.view.match}:${props.view.round}:${props.view.stage}:${props.view.phase}:${!!props.view.reveal}`)
watch(key, async (_, old) => { if (!old) return; choice.value = null; text.value = ''; error.value = ''; await nextTick(); heading.value?.focus({preventScroll:true}); window.scrollTo({top:0,behavior:'instant'}) })
async function act(type = primary.value?.type) {
  if (!type || busy.value || ended.value) return
  const v = props.view, stage = answer.value?.stage
  busy.value = true; error.value = ''
  try { await props.session.send({id:ludiActionId(),match:v.match,round:v.round,type,...(type === 'answer' ? conversation.value ? {response:'text' as const,text:text.value.trim()} : {choice:choice.value!,...(stage ? {stage} : {})} : {})}) }
  catch(e) { error.value = e instanceof Error ? e.message : 'Não foi possível guardar. Tenta novamente.' }
  finally { busy.value = false }
}
async function configure() {
  if (busy.value || !props.session.prepare) return
  busy.value = true; error.value = ''
  try { await props.session.prepare({id:ludiActionId(),revision:props.view.revision,type:'configure-again'}) }
  catch(e) { error.value = e instanceof Error ? e.message : 'Não foi possível continuar.' }
  finally { busy.value = false }
}
</script>
<template>
  <main class="ludi-page social-game" :style="{'--social-footer': `${height}px`}">
    <LudiSocialHeader :view="view" />
    <p v-if="connection?.message && !ended" class="ludi-notice" role="status">{{ connection.message }}</p>
    <section class="social-stage">
      <template v-if="ended"><p class="social-kicker">Ligação terminada</p><h1 ref="heading" tabindex="-1">Esta sala terminou.</h1><p>{{ connection?.message }}</p></template>
      <template v-else-if="view.phase === 'results' && view.summary">
        <LudiSocialGlyph :variant="0"/><p class="social-kicker">{{ view.totalRounds }} momentos juntos</p><h1 ref="heading" tabindex="-1">O vosso retrato.</h1><p class="social-intro">Revê as respostas do grupo ou descobre mais numa nova ronda.</p>
        <dl class="social-summary"><div v-if="view.summary.inTune + view.summary.divided"><dt>Escolhas em sintonia</dt><dd>{{ view.summary.inTune }}</dd></div><div v-if="view.summary.inTune + view.summary.divided"><dt>Escolhas diferentes</dt><dd>{{ view.summary.divided }}</dd></div><div v-if="view.summary.predictions"><dt>Previsões acertadas</dt><dd>{{ view.summary.correctPredictions }}<small> / {{ view.summary.predictions }}</small></dd></div><div v-if="view.summary.customAttempts"><dt>Acertos nas perguntas vossas</dt><dd>{{ view.summary.customMatches }}<small> / {{ view.summary.customAttempts }}</small></dd></div></dl>
        <p v-if="view.summary.customRemaining">Ainda há {{ view.summary.customRemaining }} perguntas vossas por descobrir.</p><p v-else-if="view.summary.customUsed" class="social-note">As perguntas vossas já foram usadas. Ao repetir, podem voltar a aparecer.</p>
        <details class="social-history"><summary>Rever o que descobrimos</summary><section v-for="(round,i) in view.history" :key="i"><p class="social-kicker">{{ i + 1 }} / {{ view.totalRounds }}</p><h2>{{ round.prompt }}</h2><p v-if="round.reveal.correctLabel"><strong>{{ round.reveal.correctLabel }}</strong></p><p v-if="round.reveal.targetSkipped">A pessoa preferiu passar.</p><p v-for="(count,j) in round.reveal.counts" :key="j">{{ round.options?.[j] }} <strong>· {{ count }}</strong></p><p v-for="p in round.reveal.contributions" :key="p.playerId"><strong>{{ p.name }}</strong> · {{ p.oral ? 'Não há texto partilhado nesta resposta.' : p.text }}</p></section></details>
        <p class="social-note">Repetir mantém este grupo. Para jogar sem alguém, criem outra sala.</p><button v-if="view.context.permissions.control" class="ludi-text-button" :disabled="busy" @click="configure">Mudar contexto ou preparar perguntas</button><NuxtLink class="ludi-text-button" to="/ludi">Escolher outro jogo</NuxtLink>
      </template>
      <template v-else-if="content">
        <p class="social-kicker">{{ label }}<span v-if="'targetName' in content && content.targetName"> · {{ content.targetName }}</span></p>
        <h1 ref="heading" tabindex="-1">{{ view.reveal ? revealTitle : content.prompt }}</h1>
        <p v-if="view.reveal" class="social-recalled">{{ content.prompt }}</p>
        <template v-if="view.reveal">
          <div v-if="view.reveal.correctLabel" class="social-discovery"><LudiSocialGlyph :label="view.reveal.correctLabel"/><strong>{{ view.reveal.correctLabel }}</strong></div>
          <p v-if="view.reveal.matches !== undefined" class="social-match">{{ view.reveal.matches }} {{ view.reveal.matches === 1 ? 'pessoa acertou' : 'pessoas acertaram' }}.</p>
          <ul v-if="view.reveal.counts" class="social-votes" aria-label="Respostas do grupo"><li v-for="(n,i) in view.reveal.counts" :key="i" :class="{correct: view.reveal.correctIndex === i}"><LudiSocialGlyph :label="options[i]" :variant="i"/><div><span>{{ options[i] }}<small v-if="view.ownChoice === i"> · escolheste esta</small></span><div class="social-vote-track" aria-hidden="true"><i :style="{width:`${n/totalVotes*100}%`}"/></div></div><strong>{{ n }}<small>{{ n === 1 ? 'pessoa' : 'pessoas' }}</small></strong></li></ul>
          <div v-if="view.reveal.contributions" class="social-contributions"><article v-for="p in view.reveal.contributions" :key="p.playerId"><h2>{{ p.name }}<small v-if="p.playerId === view.context.participantId"> · tu</small></h2><p>{{ p.oral ? 'Não há texto partilhado nesta resposta.' : p.text }}</p></article><p v-if="!view.reveal.contributions.length">Hoje ninguém quis partilhar. Tudo bem.</p></div>
          <p v-if="view.reveal.skipped" class="social-note">{{ view.reveal.skipped }} {{ view.reveal.skipped === 1 ? 'pessoa preferiu' : 'pessoas preferiram' }} passar.</p>
          <p class="social-conversation-cue">Vê as respostas ao teu ritmo. Toca em Continuar quando terminares.</p>
        </template>
        <template v-else-if="answer">
          <p class="social-intro">{{ conversation ? 'Escreve o que te apetece partilhar com o grupo. Também podes passar.' : view.stage === 'prediction' ? 'O que achas que esta pessoa vai escolher?' : view.stage === 'target-answer' ? 'O grupo já fez os seus palpites. Agora escolhe por ti.' : content.kind === 'guess' ? 'Qual será a resposta? Vai pelo teu palpite.' : 'Escolhe o que mais combina contigo.' }}</p>
          <div v-if="conversation" class="social-story"><label for="social-story">A tua história</label><textarea id="social-story" v-model="text" :disabled="busy" maxlength="500" placeholder="Uma coisa que te apeteça partilhar…" aria-describedby="story-privacy"/><span class="social-count">{{ text.length }}/500</span><p id="story-privacy" class="social-note">O texto fica visível ao grupo quando todos terminarem e permanece nesta sala até ela terminar.</p></div>
          <fieldset v-else class="social-options" :disabled="busy"><legend class="sr-only">Escolhe uma resposta</legend><label v-for="(option,i) in options" :key="i" :class="{selected: choice === i}"><input v-model="choice" type="radio" name="social-answer" :value="i"><LudiSocialGlyph :label="option" :variant="i"/><span>{{ option }}</span><i aria-hidden="true">{{ choice === i ? '✓' : '' }}</i></label></fieldset>
        </template>
        <div v-else class="social-confirmation" role="status"><LudiSocialGlyph :variant="2"/><h2>{{ view.skipped ? 'Esta passou.' : view.ownChoice !== undefined || view.ownText !== undefined || view.oralShared ? 'Ficou entre nós.' : 'Agora é com o grupo.' }}</h2><p v-if="view.ownChoice !== undefined">A tua escolha: <strong>{{ options[view.ownChoice] }}</strong></p><p v-if="view.ownText" class="social-own-text">{{ view.ownText }}</p><p v-if="view.oralShared">A tua participação está confirmada, sem texto partilhado.</p><p v-if="view.skipped">Sem precisar de explicar.</p><p>{{ wait }}</p><small>A tua participação fica guardada se precisares de voltar.</small></div>
      </template>
    </section>
    <footer ref="controls" class="social-controls" :aria-busy="busy"><div><p v-if="error" class="ludi-error" role="alert">{{ error }}</p><p v-if="view.reveal && !ended" class="social-note" role="status">{{ view.participation?.ready.length ?? 0 }} de {{ view.players.length }} prontos para continuar</p><button v-if="primary" class="ludi-primary" :disabled="busy || (primary.type === 'answer' && (conversation ? !text.trim() : choice === null))" @click="act()">{{ busy ? 'A guardar…' : primary.type === 'answer' ? conversation ? 'Partilhar resposta' : 'Confirmar resposta' : primary.label }}<span aria-hidden="true">→</span></button><NuxtLink v-else-if="ended" to="/ludi/entre-nos" class="ludi-primary">Criar outra sala →</NuxtLink><p v-else class="social-wait" role="status">{{ wait }}</p><div v-if="!ended" class="social-secondary-actions"><button v-for="a in view.actions.filter(a => a.type !== primary?.type)" :key="a.type" class="ludi-text-button" :disabled="busy" @click="act(a.type)">{{ a.type === 'skip' ? 'Passar esta pergunta' : a.label }}</button></div></div></footer>
  </main>
</template>
<style scoped>
.social-game{max-width:56rem;margin-inline:auto;padding-bottom:calc(var(--social-footer) + 2.5rem);color:#183c30}.social-stage{max-width:46rem;margin:auto}.social-stage h1{font-size:clamp(2rem,5vw,3.25rem);line-height:1.13;letter-spacing:-.045em;max-width:22ch;margin:.7rem 0 1.25rem;text-wrap:balance}.social-kicker{font-size:.78rem;font-weight:800;color:#40735b;letter-spacing:.06em;text-transform:uppercase;margin:0}.social-intro,.social-recalled{font-size:1.05rem;color:#657869;line-height:1.55;margin:0 0 1.6rem}.social-recalled{max-width:40ch}.social-options{border:0;padding:0;margin:0;display:grid;gap:.7rem}.social-options label{display:flex;gap:1rem;align-items:center;padding:1rem;border:1.5px solid #dedfd4;border-radius:19px;min-height:92px;background:#fffdf680;cursor:pointer;transition:background .15s,border-color .15s,transform .15s;position:relative}.social-options label>span{flex:1;font-size:1.08rem;line-height:1.35;font-weight:650}.social-options input{position:absolute;opacity:0;width:1px;height:1px}.social-options label:has(input:focus-visible){outline:3px solid #997930;outline-offset:4px}.social-options label.selected{border-color:#25835b;background:#eaf2e4}.social-options label:active{transform:scale(.988)}.social-options i{width:27px;height:27px;border:2px solid #d1d6c8;border-radius:50%;font-style:normal;display:grid;place-items:center;flex:none}.social-options .selected i{background:#287b55;border-color:#287b55;color:#fff}.social-note{font-size:.83rem;color:#657869;line-height:1.5}.social-story{position:relative}.social-story>label{display:block;font-weight:700;margin-bottom:.6rem}.social-story textarea{width:100%;min-height:160px;resize:vertical;border:1.5px solid #c9d2c1;border-radius:18px;padding:1.15rem 1.15rem 2.4rem;font:inherit;font-size:1.1rem;line-height:1.5;color:inherit;background:#fffdf9}.social-story textarea:focus-visible{outline:3px solid #997930;outline-offset:3px}.social-count{display:block;text-align:right;font-size:.8rem;color:#657869;margin:-2.3rem 1rem 1.1rem;position:relative;pointer-events:none}.social-story>.ludi-secondary{width:100%;margin-top:.7rem}.social-confirmation{margin:1.7rem 0;padding:1.5rem 0;border-block:1px solid #d9e0d1}.social-confirmation h2{font-size:1.5rem;margin:.6rem 0}.social-confirmation p{line-height:1.6}.social-confirmation small{color:#657869}.social-own-text{white-space:pre-wrap}.social-discovery{display:flex;gap:1.2rem;align-items:center;padding:1.5rem;background:#e7f0dd;border-radius:22px;margin:1rem 0;font-size:1.5rem;line-height:1.3}.social-discovery .social-glyph{width:4.5rem;height:4.5rem}.social-match{text-align:center;color:#3c7559;font-weight:600}.social-votes{list-style:none;margin:1.4rem 0;padding:0;display:grid;gap:.6rem}.social-votes li{display:flex;align-items:center;gap:.8rem;padding:.9rem;border:1px solid #dedfd4;border-radius:17px}.social-votes li.correct{border-color:#298b60;background:#f0f5e9}.social-votes li>div{flex:1;min-width:0}.social-votes li>div>span{font-weight:600}.social-votes small{font-size:.75rem;color:#657869;font-weight:400}.social-votes li>strong{text-align:center;min-width:3.2rem;font-size:1.15rem}.social-votes li>strong>small{display:block}.social-vote-track{height:8px;background:#e5e7dd;border-radius:20px;overflow:hidden;margin-top:.6rem}.social-vote-track i{height:100%;display:block;background:#71a786;border-radius:20px;transition:width .3s}.social-contributions article{border-left:3px solid #8fb997;padding:.2rem 1.2rem;margin:1.6rem 0}.social-contributions h2{font-size:1rem;margin:0}.social-contributions h2 small{font-weight:400}.social-contributions p{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.6;font-size:1.1rem}.social-conversation-cue{background:#edf0e7;padding:1rem 1.2rem;border-radius:16px;line-height:1.5;color:#49705a}.social-summary{margin:2rem 0}.social-summary>div{display:flex;justify-content:space-between;gap:1rem;border-bottom:1px solid #d6dfd0;padding:1rem 0;align-items:center}.social-summary dd{font-size:2.3rem;font-weight:750;margin:0}.social-summary dd small{font-size:1rem;color:#657869}.social-summary dt{max-width:20ch}.social-history{border-block:1px solid #d6dfd0;padding:1rem 0;margin:1.5rem 0}.social-history summary{cursor:pointer;font-weight:700;min-height:30px}.social-history section{padding:1.5rem 0;border-bottom:1px solid #d6dfd0}.social-history h2{font-size:1.2rem;line-height:1.4}.social-history p{white-space:pre-wrap;overflow-wrap:anywhere}.social-controls{position:fixed;bottom:0;left:0;right:0;background:#faf8f0;border-top:1px solid #d7dece;padding:.7rem max(1rem,env(safe-area-inset-left)) max(.7rem,env(safe-area-inset-bottom));z-index:5}.social-controls>div{max-width:46rem;margin:auto}.social-controls .ludi-primary{border-radius:999px;min-height:56px;background:#246447;color:#fff}.social-controls .social-note{margin:0 0 .5rem;text-align:center}.social-secondary-actions{display:flex;justify-content:center}.social-wait{margin:.45rem 0;text-align:center;font-size:.87rem;line-height:1.45;color:#4f6958}.social-secondary-actions .ludi-text-button{min-height:40px}@media(min-width:760px){.social-options{grid-template-columns:1fr 1fr}.social-options label{min-height:128px}.social-game{padding-top:1.5rem}}@media(max-width:400px){.social-options label{padding:.8rem;min-height:80px;gap:.7rem}.social-options .social-glyph{width:2.7rem;height:2.7rem}.social-stage h1{font-size:1.9rem}.social-votes .social-glyph{width:2.6rem;height:2.6rem}}@media(orientation:landscape) and (max-height:550px){.social-stage h1{font-size:1.85rem;margin:.4rem 0 .7rem}.social-options{grid-template-columns:1fr 1fr}.social-options label{min-height:74px;padding:.6rem .8rem}.social-controls{padding-top:.4rem;padding-bottom:max(.4rem,env(safe-area-inset-bottom))}.social-controls .ludi-primary{min-height:44px}.social-secondary-actions{position:absolute;right:1rem;bottom:1rem}.social-controls>div:has(.social-secondary-actions button){padding-right:10rem}.social-secondary-actions .ludi-text-button{font-size:.8rem}.social-intro{margin-bottom:.8rem}.social-story textarea{min-height:100px}}@media(prefers-reduced-motion:reduce){.social-options label,.social-vote-track i{transition:none}}
.social-controls .ludi-primary:disabled{background:#dfe6da;color:#697766;opacity:1}
</style>
